<script setup>
import {onMounted,onUnmounted,ref,computed,watch,nextTick} from 'vue'
import {VueFlow,useVueFlow} from '@vue-flow/core'
import '@vue-flow/core/dist/style.css'
import '@vue-flow/core/dist/theme-default.css'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import LearnedRuleEvidence from '../components/LearnedRuleEvidence.vue'
import {api,session} from '../lib/api.js'
import {validateAddressExpression,validatePortExpression,validateProgramPath} from '@winfire/shared/validation.js'
import {normalizeSchedule,normalizeMfaGate,extractMfaGates} from '@winfire/shared'
import {useRoute} from 'vue-router'
const route=useRoute()
const policies=ref([]),nodes=ref([]),groups=ref([]),selected=ref(null),versions=ref([]),assignments=ref([]),graphNodes=ref([]),edges=ref([]),editor=ref(null),formOpen=ref(false),assignOpen=ref(false),historyOpen=ref(false),error=ref(''),message=ref(''),newName=ref(''),newDescription=ref(''),comment=ref(''),assignKind=ref('node'),assignTarget=ref(''),busy=ref(false)
const learningPreview=ref(null),previewBusy=ref(false)
const confirmDialogOpen=ref(false),confirmDialogMessage=ref(''),confirmDialogAction=ref(null),confirmDialogBusy=ref(false)
const targetDropActive=ref(false)
const verifyOpen=ref(false),verifyVantageId=ref(''),verifyBusy=ref(false)
const verifierPeers=computed(()=>nodes.value.filter(node=>['winrm','winrms'].includes(node.transport)))
const editorMode=ref('visual')
const classicRules=computed(()=>graphNodes.value.filter(node=>['allow','deny','program'].includes(node.type)))
const compareFrom=ref(''),compareTo=ref(''),comparison=ref(null),compareBusy=ref(false)
const types=[['allow','check-circle-outline','Allow rule'],['deny','cancel','Deny rule'],['program','application-outline','Program rule'],['portGroup','numeric','Port group'],['addressGroup','ip-network','Address group'],['profile','shield-outline','Profile scope'],['schedule','clock-outline','Schedule'],['mfaGate','shield-account','MFA gate']]
const {fitView}=useVueFlow()
let resizeTimer,previewTimer
function fit(){clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>fitView({padding:.22,duration:150}),100)}
const isLearningPreview=computed(()=>selected.value?.origin==='learned'&&selected.value?.learning?.status==='active')
const activeRules=computed(()=>isLearningPreview.value?learningPreview.value?.rules||[]:versions.value.find(v=>v.id===selected.value?.current_version_id)?.rules||[])
const activeMfaGates=computed(()=>isLearningPreview.value?[]:versions.value.find(v=>v.id===selected.value?.current_version_id)?.mfaGates||extractMfaGates({nodes:graphNodes.value,edges:edges.value}))
const evidenceByNode=computed(()=>{
  const graph=isLearningPreview.value?learningPreview.value?.graph:versions.value.find(v=>v.id===selected.value?.current_version_id)?.graph
  return new Map((graph?.nodes||[]).map(node=>[node.id,node.data?.evidence]))
})
function ruleEvidence(rule){return evidenceByNode.value.get(rule.sourceNodeId)}
const canEdit=computed(()=>['owner','admin','editor'].includes(session.user?.role))
function assignmentLabel(assignment){return assignment.node_id?nodes.value.find(node=>node.id===assignment.node_id)?.hostname||assignment.node_id:groups.value.find(group=>group.id===assignment.node_group_id)?.name||assignment.node_group_id}
async function refreshAssignments(){if(selected.value)assignments.value=(await api(`/policies/${selected.value.id}`)).assignments||[]}
function nodeIssue(node){
  const data=node.data||{}
  if(node.type==='portGroup'&&!validatePortExpression(data.ports))return 'Enter ports from 1 to 65535, separated by commas.'
  if(node.type==='addressGroup'&&!validateAddressExpression(data.addresses))return 'Enter valid IP addresses, CIDRs, or ranges.'
  if(['allow','deny','program'].includes(node.type)){
    if(!validatePortExpression(data.localPort||'Any')||!validatePortExpression(data.remotePort||'Any'))return 'Use valid local and remote ports from 1 to 65535.'
    if(data.protocol==='Any'&&((data.localPort||'Any')!=='Any'||(data.remotePort||'Any')!=='Any'))return 'Specific ports require TCP or UDP.'
    if(!validateAddressExpression(data.remoteAddress||'Any'))return 'Enter a valid remote IP address or CIDR.'
    if(node.type==='program'&&!validateProgramPath(data.program))return 'Enter an absolute Windows program path.'
    if(data.localUserSid&&(!/^S-1-\d+-\d+(?:-\d+)+$/.test(data.localUserSid)||node.type!=='deny'||data.direction!=='out'))return 'Account SID restrictions require an outbound reject rule and a valid SID.'
  }
  if(node.type==='schedule'){try{normalizeSchedule(data)}catch(error){return error.message}}
  if(node.type==='mfaGate'){try{normalizeMfaGate(data)}catch(error){return error.message}}
  return ''
}
const editorIssue=computed(()=>editor.value?nodeIssue(editor.value):'')
const validationIssue=computed(()=>{
  if(!selected.value)return ''
  for(const node of graphNodes.value){const issue=nodeIssue(node);if(issue)return `${nodeLabel(node)}: ${issue}`}
  return ''
})
function nodeLabel(n){return n.data?.name||types.find(t=>t[0]===n.type)?.[2]||n.type}
function storageKey(){return `winfire_draft_${selected.value?.id}`}
async function load(){try{[policies.value,nodes.value,groups.value]=await Promise.all([api('/policies'),api('/nodes'),api('/node-groups')]);if(selected.value){selected.value=policies.value.find(p=>p.id===selected.value.id)||null}}catch(e){error.value=e.message}}
async function refreshLearningPreview(policy=selected.value){if(!policy||policy.learning?.status!=='active')return;previewBusy.value=true;try{const preview=await api(`/policies/${policy.id}/learning-preview`);if(selected.value?.id!==policy.id)return;learningPreview.value=preview;graphNodes.value=preview.graph.nodes.map(n=>({...n,data:{...n.data,label:nodeLabel(n)}}));edges.value=preview.graph.edges;error.value='';await nextTick();fit()}catch(e){error.value=e.message}finally{previewBusy.value=false}}
async function choose(policy){selected.value=policy;learningPreview.value=null;[versions.value]=await Promise.all([api(`/policies/${policy.id}/versions`),refreshAssignments()]);compareFrom.value=versions.value[1]?.id||versions.value[0]?.id||'';compareTo.value=policy.current_version_id||versions.value[0]?.id||'';comparison.value=null;if(isLearningPreview.value){await refreshLearningPreview(policy);return}const draft=localStorage.getItem(storageKey());const current=versions.value.find(v=>v.id===policy.current_version_id);const graph=draft?JSON.parse(draft):current?.graph||{nodes:[],edges:[]};graphNodes.value=graph.nodes.map(n=>({...n,data:{direction:'in',protocol:'TCP',localPort:'Any',remotePort:'Any',remoteAddress:'Any',profile:'Any',program:'Any',...n.data,label:nodeLabel(n)}}));edges.value=graph.edges;error.value='';message.value='';await nextTick();fit()}
watch([graphNodes,edges],()=>{if(selected.value&&!isLearningPreview.value)localStorage.setItem(storageKey(),JSON.stringify({nodes:graphNodes.value,edges:edges.value}))},{deep:true})
onMounted(async()=>{await load();const requested=policies.value.find(policy=>policy.id===route.query.policyId);if(requested)await choose(requested);window.addEventListener('resize',fit);previewTimer=setInterval(async()=>{if(!isLearningPreview.value)return;const policyId=selected.value.id;await load();if(selected.value?.id!==policyId)return;if(isLearningPreview.value)await refreshLearningPreview();else await choose(selected.value)},60_000)})
onUnmounted(()=>{window.removeEventListener('resize',fit);clearTimeout(resizeTimer);clearInterval(previewTimer)})
async function create(){try{const policy=await api('/policies',{method:'POST',body:{name:newName.value,description:newDescription.value}});formOpen.value=false;newName.value='';newDescription.value='';await load();await choose(policy)}catch(e){error.value=e.message}}
function addNode(type){const index=graphNodes.value.length;const data={name:types.find(t=>t[0]===type)?.[2],label:types.find(t=>t[0]===type)?.[2],direction:'in',protocol:'TCP',localPort:'Any',remotePort:'Any',remoteAddress:'Any',profile:'Any',program:'Any'};if(type==='schedule')Object.assign(data,{days:'1,2,3,4,5',startTime:'09:00',endTime:'17:00',timezone:'UTC'});if(type==='mfaGate')Object.assign(data,{localPort:'3389',program:'Any',sourceAssetScope:'Any',destinationAssetScope:'Any',sourceProcess:'Any',extraPorts:'',fallbackToLoggedOnUser:false,failMode:'closed',sessionTtlMinutes:480,reactiveTtlMinutes:240,entraGroupId:''});graphNodes.value.push({id:crypto.randomUUID(),type,position:{x:80+(index%3)*230,y:80+Math.floor(index/3)*140},data})}
function removeClassicRule(node){graphNodes.value=graphNodes.value.filter(item=>item.id!==node.id);edges.value=edges.value.filter(edge=>edge.source!==node.id&&edge.target!==node.id)}
function connect(connection){edges.value=[...edges.value,{...connection,id:crypto.randomUUID()}]}
async function save(){busy.value=true;error.value='';try{const graph={nodes:graphNodes.value.map(n=>({id:n.id,type:n.type,position:n.position,data:Object.fromEntries(Object.entries(n.data||{}).filter(([k])=>k!=='label'))})),edges:edges.value.map(e=>({id:e.id,source:e.source,target:e.target}))};await api(`/policies/${selected.value.id}/versions`,{method:'POST',body:{graph,comment:comment.value}});localStorage.removeItem(storageKey());comment.value='';message.value='Version saved. An administrator can sync it from the top bar.';await load();await choose(selected.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function assignTargetToPolicy(kind,target){
  if(!selected.value||!canEdit.value||busy.value)return
  busy.value=true;error.value='';message.value=''
  try{
    await api(`/policies/${selected.value.id}/assignments`,{method:'POST',body:kind==='node'?{nodeId:target}:{nodeGroupId:target}})
    assignOpen.value=false;assignTarget.value='';await refreshAssignments()
    message.value=kind==='node'?'Node assigned':target==='winfire-global-all-nodes'?'Global policy assigned':'Node group assigned'
  }catch(e){error.value=e.message}
  finally{busy.value=false}
}
async function assign(){await assignTargetToPolicy(assignKind.value,assignKind.value==='global'?'winfire-global-all-nodes':assignTarget.value)}
function dragTarget(event,kind,target){
  if(!canEdit.value||busy.value){event.preventDefault();return}
  event.dataTransfer.effectAllowed='copy'
  event.dataTransfer.setData('application/x-winfire-target',JSON.stringify({kind,target}))
}
function dropTarget(event){
  targetDropActive.value=false
  if(!canEdit.value||busy.value)return
  let payload
  try{payload=JSON.parse(event.dataTransfer.getData('application/x-winfire-target'))}catch{return}
  if(payload.kind==='node'&&nodes.value.some(node=>node.id===payload.target))assignTargetToPolicy('node',payload.target)
  else if(payload.kind==='group'&&groups.value.some(group=>group.id===payload.target))assignTargetToPolicy('group',payload.target)
}
function askConfirmation(message,action){confirmDialogMessage.value=message;confirmDialogAction.value=action;confirmDialogOpen.value=true}
async function runConfirmation(){const action=confirmDialogAction.value;confirmDialogOpen.value=false;confirmDialogAction.value=null;if(action){confirmDialogBusy.value=true;try{await action()}finally{confirmDialogBusy.value=false}}}
function removeAssignment(assignment){askConfirmation(`Remove the assignment to ${assignmentLabel(assignment)}? Managed firewall rules will be removed from nodes that no longer have this policy.`,async()=>{
  busy.value=true;error.value='';message.value=''
  try{const result=await api(`/policies/${selected.value.id}/assignments/${assignment.id}`,{method:'DELETE'});await refreshAssignments();message.value=result.queued?'Agent firewall cleanup queued. The assignment will disappear after the agent confirms removal.':`Assignment removed; cleaned ${result.cleanedNodes.length} node(s)`}
  catch(e){error.value=e.message}
  finally{busy.value=false}
})}
async function apply(){busy.value=true;try{const result=await api(`/policies/${selected.value.id}/apply`,{method:'POST',body:{}});message.value=`Applied to ${result.results.filter(r=>r.status==='success').length} node(s); ${result.results.filter(r=>r.status==='failed').length} failed` }catch(e){error.value=e.message}finally{busy.value=false}}
async function verifyPolicy(){
  if(!selected.value)return
  verifyBusy.value=true;error.value='';message.value=''
  try{
    const result=await api('/verifier/runs',{method:'POST',body:{policyId:selected.value.id,...(verifyVantageId.value?{vantageNodeId:verifyVantageId.value}:{})}})
    verifyOpen.value=false
    const passed=result.results.filter(item=>item.status==='pass').length,failed=result.results.filter(item=>item.status==='fail').length
    message.value=`Verification complete: ${passed} passed, ${failed} failed, ${result.results.length-passed-failed} inconclusive. See Reports → Verification for evidence.`
    await load()
  }catch(cause){error.value=cause.message}
  finally{verifyBusy.value=false}
}
async function recall(version){busy.value=true;try{await api(`/policies/${selected.value.id}/versions/${version.id}/recall`,{method:'POST',body:{}});historyOpen.value=false;message.value=`Recalled version ${version.version_no}. Sync it from the top bar.`;await load();await choose(selected.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function compareVersions(){compareBusy.value=true;comparison.value=null;error.value='';try{comparison.value=await api(`/policies/${selected.value.id}/diff?from=${encodeURIComponent(compareFrom.value)}&to=${encodeURIComponent(compareTo.value)}`)}catch(e){error.value=e.message}finally{compareBusy.value=false}}
function describeRule(rule){return `${rule.name}: ${rule.action} ${rule.direction} ${rule.protocol} local ${rule.localPort||'Any'} / remote ${rule.remotePort||'Any'} / ${rule.remoteAddress||'Any'}`}
function describeNode(node){return `${nodeLabel(node)} (${node.type})`}
</script>
<template><div class="view"><PageHeader eyebrow="POLICY / AUTHORING" title="Policy studio" description="Compose, version and apply Windows Firewall rules"><button class="button primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> New policy</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="studio-layout"><aside class="panel glass policy-list" aria-label="Policy library"><div class="panel-title"><div><span class="eyebrow">LIBRARY</span><h2>Policies</h2></div><span class="count-chip">{{policies.length}}</span></div><button v-for="policy in policies" :key="policy.id" class="policy-item" :class="{active:selected?.id===policy.id}" @click="choose(policy)"><i class="mdi mdi-shield-outline"></i><span><strong>{{policy.name}}</strong><small>{{policy.origin==='learned'?`Personal · ${policy.learning?.status||'ready'}`:`Version ${policy.version_no||'draft'}`}}</small></span><span class="status" :class="policy.learning?.status==='active'?'learning':policy.verificationStatus||'unknown'">{{policy.learning?.status==='active'?'Learning':policy.verificationStatus||'Unchecked'}}</span><i class="mdi mdi-chevron-right"></i></button><div v-if="!policies.length" class="empty-side">Create a policy to start building rules.</div></aside><div v-if="selected" class="studio-main"><section class="panel glass canvas-panel"><div class="panel-title studio-title"><div><span class="eyebrow">{{isLearningPreview?'LIVE LEARNING PREVIEW':'VISUAL POLICY EDITOR'}}</span><h2>{{selected.name}}</h2></div><div class="inline-actions"><button class="button small secondary" @click="historyOpen=true"><i class="mdi mdi-history"></i> History</button><button v-if="!isLearningPreview" class="button small secondary" @click="verifyOpen=true"><i class="mdi mdi-radar"></i> Verify</button><button v-if="!isLearningPreview" class="button small secondary" @click="assignOpen=true"><i class="mdi mdi-link-variant"></i> Assign</button></div></div><div v-if="isLearningPreview" class="learning-preview-summary"><div><strong>{{learningPreview?.rules.length||0}} proposed rules</strong><span>{{learningPreview?.newFlowCount||0}} new rules · {{learningPreview?.observedFlowCount||0}} observed 5-tuples</span><small>Training ends {{new Date(selected.learning.ends_at).toLocaleString()}}<template v-if="learningPreview?.progressiveEnabled"> · next progressive apply {{new Date(learningPreview.nextProgressiveAt).toLocaleString()}}</template></small></div><button class="button small secondary" :disabled="previewBusy" @click="refreshLearningPreview()">{{previewBusy?'Refreshing…':'Refresh preview'}}</button></div><div v-if="!isLearningPreview" class="editor-mode-tabs"><button class="button small secondary" :class="{active:editorMode==='visual'}" @click="editorMode='visual';fit()">Flow editor</button><button class="button small secondary" :class="{active:editorMode==='classic'}" @click="editorMode='classic'">Classic rules</button></div><div v-if="!isLearningPreview" v-show="editorMode==='visual'" class="palette"><button v-for="type in types" :key="type[0]" @click="addNode(type[0])"><i class="mdi" :class="`mdi-${type[1]}`"></i>{{type[2]}}</button></div><div v-show="isLearningPreview||editorMode==='visual'" class="flow-area"><VueFlow v-model:nodes="graphNodes" v-model:edges="edges" :fit-view-on-init="true" :nodes-draggable="!isLearningPreview" :nodes-connectable="!isLearningPreview" @connect="connect" @node-click="({node})=>{if(!isLearningPreview)editor=node}" /></div><div v-if="!isLearningPreview&&editorMode==='classic'" class="classic-policy-editor"><div class="inline-actions"><button class="button small secondary" @click="addNode('allow')">Add allow rule</button><button class="button small secondary" @click="addNode('deny')">Add reject rule</button></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Action</th><th>Direction</th><th>Protocol</th><th>Local port</th><th>Remote port</th><th>Remote address</th><th>Profile</th><th>Program</th><th>Local account SID</th><th></th></tr></thead><tbody><tr v-for="rule in classicRules" :key="rule.id"><td><input v-model="rule.data.name" @input="rule.data.label=rule.data.name" aria-label="Rule name"></td><td><select v-model="rule.type" aria-label="Rule action" @change="rule.data.program=rule.type==='program'?rule.data.program||'Any':'Any'"><option value="allow">Allow</option><option value="deny">Reject</option><option value="program">Program</option></select></td><td><select v-model="rule.data.direction" aria-label="Direction"><option value="in">Inbound</option><option value="out">Outbound</option></select></td><td><select v-model="rule.data.protocol" aria-label="Protocol"><option>TCP</option><option>UDP</option><option>Any</option></select></td><td><input v-model="rule.data.localPort" aria-label="Local port"></td><td><input v-model="rule.data.remotePort" aria-label="Remote port"></td><td><input v-model="rule.data.remoteAddress" aria-label="Remote address"></td><td><select v-model="rule.data.profile" aria-label="Profile"><option>Any</option><option>Domain</option><option>Private</option><option>Public</option></select></td><td><input v-model="rule.data.program" :disabled="rule.type!=='program'" aria-label="Program path"></td><td><input v-model.trim="rule.data.localUserSid" :disabled="rule.type!=='deny'" aria-label="Local account SID" placeholder="All accounts"></td><td><button class="button small danger" :aria-label="`Delete ${rule.data.name}`" @click="removeClassicRule(rule)">Delete</button></td></tr><tr v-if="!classicRules.length"><td colspan="11">No rules yet. Add one above.</td></tr></tbody></table></div></div><div v-if="!isLearningPreview" class="canvas-footer"><input v-model="comment" placeholder="Version comment (optional)" aria-label="Version comment"><span class="hint">Draft saved locally</span><span v-if="validationIssue" class="validation-hint" role="alert">{{validationIssue}}</span><button class="button primary" :disabled="busy||!!validationIssue" @click="save"><i class="mdi mdi-content-save-outline"></i> Save version</button></div></section><section class="panel glass rules-panel"><div class="panel-title"><div><span class="eyebrow">COMPILED OUTPUT</span><h2>{{activeRules.length}} {{isLearningPreview?'proposed':'active'}} rules</h2></div></div><div v-if="activeMfaGates.length" class="mfa-gate-summary"><div v-for="gate in activeMfaGates" :key="gate.id" class="rule-row"><span class="status unknown">MFA gate</span><strong>{{gate.name}}</strong><span>TCP {{gate.targetPort}} · session {{gate.sessionTtlMinutes}}m · reactive {{gate.reactiveTtlMinutes}}m</span><span v-if="gate.entraGroupId" class="mono">Entra {{gate.entraGroupId}}</span><small>Staged metadata; deployment waits for the Windows challenge broker.</small></div></div><div v-if="!activeRules.length&&!activeMfaGates.length" class="empty-side">{{isLearningPreview?'No eligible traffic has been learned yet.':'Save a version to see compiled rules.'}}</div><div v-for="rule in activeRules" :key="rule.sourceNodeId" class="rule-row"><span class="status" :class="rule.action">{{rule.action}}</span><strong>{{rule.name}}</strong><span>{{rule.direction}} / {{rule.protocol}} / local {{rule.localPort}} / remote {{rule.remotePort||'Any'}}</span><span class="mono">{{rule.remoteAddress}}</span><span v-if="rule.localUserSid" class="mono">Account {{rule.localUserSid}}</span><LearnedRuleEvidence v-if="ruleEvidence(rule)" :evidence="ruleEvidence(rule)" /></div></section><section class="panel glass assignments-panel" :class="{'target-drop-active':targetDropActive}" @dragover.prevent="targetDropActive=true" @dragleave="targetDropActive=false" @drop.prevent="dropTarget"><div class="panel-title"><div><span class="eyebrow">TARGETS</span><h2>Assignments</h2></div><span class="count-chip">{{assignments.length}}</span></div><div v-if="canEdit&&!isLearningPreview" class="assignment-targets"><p>Drag a node or group here, or select one below to assign it.</p><button v-for="node in nodes.filter(item=>!assignments.some(assignment=>assignment.node_id===item.id))" :key="`node-${node.id}`" type="button" class="assignment-target-chip" draggable="true" :disabled="busy" @dragstart="dragTarget($event,'node',node.id)" @click="assignTargetToPolicy('node',node.id)"><i class="mdi mdi-server"></i> {{node.hostname}}</button><button v-for="group in groups.filter(item=>!assignments.some(assignment=>assignment.node_group_id===item.id))" :key="`group-${group.id}`" type="button" class="assignment-target-chip" draggable="true" :disabled="busy" @dragstart="dragTarget($event,'group',group.id)" @click="assignTargetToPolicy('group',group.id)"><i class="mdi mdi-server-network"></i> {{group.name}}</button></div><p v-if="!assignments.length" class="empty-side">No nodes or groups assigned yet.</p><div v-for="assignment in assignments" :key="assignment.id" class="assignment-row"><span><i class="mdi" :class="assignment.node_id?'mdi-server':'mdi-server-network'"></i> {{assignmentLabel(assignment)}} <small>{{assignment.node_id?'Node':'Group'}}</small></span><button v-if="canEdit" class="button small secondary" :disabled="busy||!!assignment.removal_job_id" :aria-label="`Remove assignment to ${assignmentLabel(assignment)}`" @click="removeAssignment(assignment)">{{assignment.removal_job_id?'Removal queued':'Remove'}}</button></div></section></div><section v-else class="panel glass studio-empty"><i class="mdi mdi-source-branch"></i><h2>Select a policy</h2><p>Choose an existing policy or create one to open the visual editor.</p></section></div><GlassWindow :model-value="!!editor" @update:model-value="editor=null" :title="`Edit ${editor?.type||'node'}`"><div v-if="editor" class="form-grid"><label>Name<input v-model="editor.data.name" @input="editor.data.label=editor.data.name"></label><template v-if="['allow','deny','program'].includes(editor.type)"><label>Direction<select v-model="editor.data.direction"><option value="in">Inbound</option><option value="out">Outbound</option></select></label><label>Protocol<select v-model="editor.data.protocol"><option>TCP</option><option>UDP</option><option>Any</option></select></label><label>Local port<input v-model="editor.data.localPort" placeholder="3389 or Any"></label><label>Remote port<input v-model="editor.data.remotePort" placeholder="443 or Any"></label><label>Remote address<input v-model="editor.data.remoteAddress" placeholder="Any or CIDR"></label><label v-if="editor.type==='program'">Program path<input v-model="editor.data.program" placeholder="C:\Program Files\app.exe"></label><label v-if="editor.type==='deny'">Local account SID<input v-model.trim="editor.data.localUserSid" placeholder="All accounts"></label><label>Profile<select v-model="editor.data.profile"><option>Any</option><option>Domain</option><option>Private</option><option>Public</option></select></label></template><label v-if="editor.type==='portGroup'">Ports<input v-model="editor.data.ports" placeholder="80,443"></label><label v-if="editor.type==='addressGroup'">Addresses<input v-model="editor.data.addresses" placeholder="10.0.0.0/8"></label><label v-if="editor.type==='profile'">Profile<select v-model="editor.data.profile"><option>Any</option><option>Domain</option><option>Private</option><option>Public</option></select></label><template v-if="editor.type==='schedule'"><label>Days (0 Sunday – 6 Saturday)<input v-model="editor.data.days" placeholder="1,2,3,4,5"></label><label>Start time<input v-model="editor.data.startTime" type="time"></label><label>End time<input v-model="editor.data.endTime" type="time"></label><label>Timezone<input v-model="editor.data.timezone" placeholder="UTC or America/Chicago"></label><p class="hint">Connect this window to an allow/reject rule. Outside the window, the scheduler removes that rule and reapplies it at the next transition.</p></template><template v-if="editor.type==='mfaGate'"><label>Target TCP port(s)<input v-model="editor.data.localPort" placeholder="3389"></label><label>Program<input v-model="editor.data.program" placeholder="Any or C:\\Program Files\\App\\app.exe"></label><label>Source asset scope<input v-model="editor.data.sourceAssetScope" placeholder="Any, node ID, or group ID"></label><label>Destination asset scope<input v-model="editor.data.destinationAssetScope" placeholder="Any, node ID, or group ID"></label><label>Source process<input v-model="editor.data.sourceProcess" placeholder="Any or C:\\Program Files\\Client\\client.exe"></label><label>Extra TCP ports<input v-model="editor.data.extraPorts" placeholder="22,5985"></label><label>Entra group ID<input v-model.trim="editor.data.entraGroupId" placeholder="Optional group object ID"></label><label>Session TTL (minutes)<input v-model.number="editor.data.sessionTtlMinutes" type="number" min="1" max="10080"></label><label>Reactive rule TTL (minutes)<input v-model.number="editor.data.reactiveTtlMinutes" type="number" min="1" max="10080"></label><label>Unavailable behavior<select v-model="editor.data.failMode"><option value="closed">Fail closed</option><option value="open">Fail open</option></select></label><label class="check-label"><input v-model="editor.data.fallbackToLoggedOnUser" type="checkbox"> Fall back to logged-on user</label><p class="hint">This gate is saved as policy metadata. Deployment remains blocked until the Windows challenge broker is available.</p></template><p v-if="editorIssue" class="error-msg" role="alert">{{editorIssue}}</p><div class="form-actions"><button class="button danger" @click="graphNodes=graphNodes.filter(n=>n.id!==editor.id);edges=edges.filter(e=>e.source!==editor.id&&e.target!==editor.id);editor=null">Delete node</button><button class="button primary" @click="editor=null">Done</button></div></div></GlassWindow><GlassWindow v-model="formOpen" title="New policy"><form class="form-grid" @submit.prevent="create"><label>Policy name<input v-model="newName" required placeholder="Production RDP access"></label><label>Description<textarea v-model="newDescription" placeholder="What this policy controls"></textarea></label><div class="form-actions"><button class="button primary">Create policy</button></div></form></GlassWindow><GlassWindow v-model="assignOpen" title="Assign policy"><div class="form-grid"><label>Target type<select v-model="assignKind" @change="assignTarget=''"><option value="node">Node</option><option value="group">Node group</option><option value="global">All nodes (global)</option></select></label><label v-if="assignKind==='node'">Node<select v-model="assignTarget"><option value="">Select a node</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select></label><label v-else-if="assignKind==='group'">Node group<select v-model="assignTarget"><option value="">Select a group</option><option v-for="group in groups.filter(item=>item.id!=='winfire-global-all-nodes')" :key="group.id" :value="group.id">{{group.name}}</option></select></label><p v-else>Apply this policy to every node, including nodes added later.</p><div class="form-actions"><button class="button primary" :disabled="assignKind!=='global'&&!assignTarget" @click="assign">Assign</button></div></div></GlassWindow><GlassWindow v-model="verifyOpen" title="Verify policy" width="520px"><form class="form-grid" @submit.prevent="verifyPolicy"><p>Probe inbound TCP rules from the control plane or from a managed Windows peer. The peer uses its assigned WinRM credential and does not change firewall rules.</p><label>Probe from<select v-model="verifyVantageId"><option value="">Control plane server</option><option v-for="node in verifierPeers" :key="node.id" :value="node.id">{{node.hostname}}</option></select></label><p v-if="verifyVantageId" class="hint">Checks against the peer itself will be inconclusive; select another peer to test that node.</p><div class="form-actions"><button type="button" class="button secondary" @click="verifyOpen=false">Cancel</button><button class="button primary" :disabled="verifyBusy">{{verifyBusy?'Verifying…':'Run verification'}}</button></div></form></GlassWindow><GlassWindow v-model="historyOpen" title="Version history"><div v-for="version in versions" :key="version.id" class="history-row"><div><strong>Version {{version.version_no}}</strong><small>{{version.comment||'No comment'}} · {{new Date(version.created_at).toLocaleString()}}</small></div><button class="button small secondary" :disabled="busy||version.id===selected?.current_version_id" @click="recall(version)">Recall</button></div><div v-if="!versions.length" class="empty-side">No saved versions yet.</div><div v-if="versions.length>1" class="form-grid" style="margin-top:1rem"><h3>Compare versions</h3><label>From<select v-model="compareFrom" @change="comparison=null"><option v-for="version in versions" :key="version.id" :value="version.id">Version {{version.version_no}}</option></select></label><label>To<select v-model="compareTo" @change="comparison=null"><option v-for="version in versions" :key="version.id" :value="version.id">Version {{version.version_no}}</option></select></label><button class="button secondary" :disabled="compareBusy||!compareFrom||!compareTo||compareFrom===compareTo" @click="compareVersions">Show changes</button></div><div v-if="comparison" class="version-diff" aria-live="polite"><h3>Version {{comparison.from.versionNo}} → {{comparison.to.versionNo}}</h3><h4>Canvas nodes</h4><ul><li v-for="node in comparison.graph.addedNodes" :key="`added-${node.id}`">Added {{describeNode(node)}}</li><li v-for="node in comparison.graph.removedNodes" :key="`removed-${node.id}`">Removed {{describeNode(node)}}</li><li v-for="change in comparison.graph.changedNodes" :key="`changed-${change.after.id}`">Changed {{describeNode(change.after)}}<details><summary>Show fields</summary><pre>Before: {{JSON.stringify({position:change.before.position,data:change.before.data},null,2)}}
After: {{JSON.stringify({position:change.after.position,data:change.after.data},null,2)}}</pre></details></li></ul><h4>Connections</h4><ul><li v-for="edge in comparison.graph.addedEdges" :key="`added-${edge.source}-${edge.target}`">Added {{edge.source}} → {{edge.target}}</li><li v-for="edge in comparison.graph.removedEdges" :key="`removed-${edge.source}-${edge.target}`">Removed {{edge.source}} → {{edge.target}}</li></ul><h4>Compiled firewall rules</h4><ul><li v-for="rule in comparison.added" :key="`added-${rule.sourceNodeId}`">Added {{describeRule(rule)}}</li><li v-for="rule in comparison.removed" :key="`removed-${rule.sourceNodeId}`">Removed {{describeRule(rule)}}</li></ul><p v-if="!comparison.graph.addedNodes.length&&!comparison.graph.removedNodes.length&&!comparison.graph.changedNodes.length&&!comparison.graph.addedEdges.length&&!comparison.graph.removedEdges.length&&!comparison.added.length&&!comparison.removed.length">No changes between these versions.</p></div></GlassWindow><ConfirmDialog v-model="confirmDialogOpen" :message="confirmDialogMessage" :busy="confirmDialogBusy" @confirm="runConfirmation" /></div></template>

